// Usage (from apps/web): node src/scene/env/hdri/bake-fallback.mjs <shipped.hdr> <out.ts> [halvings]
// Shrinks a shipped, already graded HDRI into the tiny boot fallback the venue inlines, written
// as a module exporting a base64 data URL because Vite cannot ?inline an .hdr; see SOURCES.md.
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { decodeRadiance, downsampleHalf, encodeRadiance } from './bake.ts';

const [source, target, halvings = '4'] = process.argv.slice(2);
if (!source || !target) {
  console.error('Usage: node bake-fallback.mjs <shipped.hdr> <out.ts> [halvings]');
  process.exit(1);
}
const input = await readFile(source);
let image = decodeRadiance(
  input.buffer.slice(input.byteOffset, input.byteOffset + input.byteLength),
);
for (let i = 0; i < Number(halvings); i += 1) image = downsampleHalf(image);
const output = encodeRadiance(image);
const sha = createHash('sha256').update(output).digest('hex');
const base64 = Buffer.from(output).toString('base64');
await writeFile(
  target,
  `// Generated by bake-fallback.mjs from the shipped HDRI (${image.width}×${image.height} RGBE, sha256 ${sha}); do not edit.\n` +
    `export default 'data:image/vnd.radiance;base64,${base64}';\n`,
);
console.info(
  `${target}: ${image.width}×${image.height}, ${output.byteLength} bytes, sha256 ${sha}`,
);
